function aboutPage() {
  return `<main id="main">${pageHero('Инженерная команда,<br>которая отвечает за результат', 'ООО «ЭлектроСлужба» производит электрощитовое оборудование в Минске с 2012 года.', '04', 'О компании')}
  <section class="section"><div class="shell split"><div class="split__image reveal"><img src="/wp-content/uploads/ab4edc717c498b1e01b5cb7565455259431ae739.png" alt="Компоненты электрощита" loading="lazy"></div><div><p class="eyebrow">О производстве</p><h2>От типового щита до индивидуальной автоматики</h2><p class="lead">Собираем щиты учёта, освещения, распределения, АВР, вводно-распределительные устройства, ящики и пульты управления.</p><ul class="feature-list"><li><span>Профессиональное сопровождение заказа на всех этапах</span></li><li><span>Сжатые сроки расчёта и производства</span></li><li><span>Доставка изделий на объекты</span></li><li><span>Гарантия на оборудование до 5 лет</span></li></ul></div></div></section>
  <section class="section section--blue"><div class="shell"><div class="section-head"><div><p class="eyebrow">Надёжность</p><h2>Качество, подтверждённое требованиями</h2></div><p>Продукция соответствует ТР ТС 004/2011 и 020/2011. Система менеджмента качества сертифицирована по ISO 9001:2015.</p></div><div class="info-grid"><article class="info-card reveal"><span class="index">01</span><h3>Контроль сборки</h3><p>Проверяем соответствие схемам и качество монтажа до передачи заказчику.</p></article><article class="info-card reveal"><span class="index">02</span><h3>Проверенные компоненты</h3><p>Согласуем производителей и характеристики аппаратуры до запуска.</p></article><article class="info-card reveal"><span class="index">03</span><h3>Документация</h3><p>Передаём комплект документов вместе с готовым оборудованием.</p></article></div></div></section>
  <section class="section"><div class="shell article-grid"><div class="article-grid__aside"><p class="eyebrow">Подход к работе</p><h2>Инженерное решение вместо случайного набора компонентов</h2></div><div class="prose"><h3>Сначала понимаем объект</h3><p>До расчёта выясняем назначение оборудования, режимы питания, типы нагрузок, требования к резервированию и условия монтажа. Это помогает избежать лишних компонентов и одновременно не потерять важные функции.</p><h3>Согласуем состав до производства</h3><p>Заказчик получает понятное предложение по аппаратуре и исполнению. При необходимости сравниваем несколько вариантов комплектующих по стоимости и доступности.</p><h3>Собираем с расчётом на обслуживание</h3><p>Внутренняя компоновка, маркировка и кабельные трассы должны быть понятны не только сборщику, но и специалисту, который будет обслуживать оборудование на объекте.</p></div></div></section>
  <section class="section section--dark"><div class="shell"><div class="section-head"><div><p class="eyebrow">Опыт отраслей</p><h2>Работаем с разными типами объектов</h2></div><p>Среди заказчиков компании — промышленные предприятия, энергетика, торговые сети, строительные и электромонтажные организации Беларуси.</p></div><div class="topic-grid"><article class="topic-card"><span class="topic-card__icon">01</span><h3>Энергетика и промышленность</h3><p>Распределительные устройства, панели и шкафы управления для ответственных нагрузок.</p></article><article class="topic-card"><span class="topic-card__icon">02</span><h3>Жилая недвижимость</h3><p>ВРУ, этажные щиты, учёт и распределение для новых и реконструируемых зданий.</p></article><article class="topic-card"><span class="topic-card__icon">03</span><h3>Торговля и логистика</h3><p>Силовое питание, освещение и автоматика для магазинов, складов и комплексов.</p></article><article class="topic-card"><span class="topic-card__icon">04</span><h3>Инженерные системы</h3><p>Управление вентиляцией, насосами, котельными и другими установками.</p></article></div></div></section>${faqSection(commonFaq, 'О сотрудничестве')}${cta()}</main>`;
}

