function careersPage() {
  return `<main id="main">${pageHero('Работа, в которой<br>виден результат', 'Приглашаем электромонтажника по сборке электротехнических шкафов в Минске.', '06', 'Вакансии')}
  <section class="section"><div class="shell"><div class="vacancy-banner"><div><p class="eyebrow" style="color:var(--lime)">Открытая вакансия</p><h2>Электромонтажник по сборке электрощитов</h2><p>Минск · полная занятость · график 5/2 · опыт 1–3 года</p></div><a class="btn btn--light" href="mailto:info@esle.by?subject=Отклик%20на%20вакансию%20электромонтажника">Откликнуться →</a></div><div class="section" style="padding-bottom:0"><div class="info-grid"><article class="info-card"><span class="index">01</span><h3>Задачи</h3><p>Гибка шин, пробивка отверстий, монтаж аппаратов, ручек и сигнальной арматуры, полная сборка шкафов.</p></article><article class="info-card"><span class="index">02</span><h3>Требования</h3><p>Среднее специальное образование, чтение схем, владение слесарным инструментом, аккуратность.</p></article><article class="info-card"><span class="index">03</span><h3>Условия</h3><p>Трудовой контракт, испытательный срок до двух месяцев; возможны подряд и совместительство.</p></article></div></div></div></section>
  <section class="section section--dark"><div class="shell article-grid"><div class="article-grid__aside"><p class="eyebrow">Рабочий процесс</p><h2>Сборка полного цикла</h2></div><div class="prose"><h3>Подготовка корпуса</h3><p>Разметка, механическая обработка, установка монтажной панели, дверной аппаратуры и кабельных вводов.</p><h3>Монтаж и соединения</h3><p>Установка коммутационных аппаратов, изоляторов и шин, прокладка силовых и управляющих цепей по документации.</p><h3>Проверка результата</h3><p>Контроль соединений, маркировки и соответствия принципиальной схеме перед передачей готового изделия.</p></div></div></section>${faqSection([['Какой опыт требуется?','Для открытой вакансии указан опыт от одного до трёх лет и умение читать принципиальные схемы.'],['Где находится производство?','Рабочее место находится в Минске, в районе станции метро «Автозаводская».'],['Какой график работы?','Полная занятость, пятидневная рабочая неделя и восьмичасовой рабочий день.'],['Как отправить отклик?','Направьте краткую информацию об опыте на info@esle.by или свяжитесь по телефону.']], 'О вакансии')}${cta('Хотите стать частью команды?')}</main>`;
}

function deliveryPage() {
  return `<main id="main">${pageHero('Доставка<br>и оплата', 'Согласуем удобный способ получения оборудования и условия расчёта до запуска заказа.', '07', 'Доставка и оплата')}
  <section class="section"><div class="shell"><div class="info-grid"><article class="info-card"><span class="index">01</span><h3>Самовывоз</h3><p>Готовый заказ можно получить на производстве: Минск, пер. Бехтерева, 8.</p></article><article class="info-card"><span class="index">02</span><h3>Доставка на объект</h3><p>Организуем доставку готовых изделий. Стоимость и срок рассчитываются для конкретного адреса.</p></article><article class="info-card"><span class="index">03</span><h3>Безналичный расчёт</h3><p>Работаем по договору и выставленному счёту. Возможность отсрочки обсуждается индивидуально.</p></article></div></div></section>
  <section class="section section--dark"><div class="shell article-grid"><div class="article-grid__aside"><p class="eyebrow">Перед отгрузкой</p><h2>Оборудование готовим к безопасной перевозке</h2></div><div class="prose"><h3>Проверяем комплектность</h3><p>До упаковки сверяем изделие, документацию и дополнительные принадлежности с составом заказа.</p><h3>Защищаем при транспортировке</h3><p>Способ упаковки зависит от габаритов, массы, выступающих органов управления и расстояния перевозки.</p><h3>Согласуем приёмку</h3><p>Перед отгрузкой сообщаем о готовности и согласуем время, транспорт и контактное лицо на объекте.</p></div></div></section>${faqSection([['Можно забрать заказ самостоятельно?','Да, самовывоз доступен с производства в Минске после согласования времени.'],['Доставляете ли вы по Беларуси?','Да, возможность и стоимость доставки рассчитываются для адреса и характеристик груза.'],['Как происходит оплата?','Условия фиксируются в договоре и счёте. Основной формат — безналичный расчёт.'],['Можно ли получить отсрочку платежа?','Такая возможность обсуждается индивидуально и зависит от условий сотрудничества.']], 'Доставка и документы')}${cta('Уточнить условия для заказа')}</main>`;
}

function productPage(key) {
  const m = modelCatalog[key];
  if (!m) return catalogPage();
  const cat = categories.find(c => c.slug === m.category);
  const related = (products[m.category] || []).filter(p => !p[0].includes(m.code) && p[0] !== m.title).slice(0,3);
  const productFaq = [
    ['Можно ли изменить типовую схему?', `Да. ${m.title} изготавливается под параметры объекта: можно изменить состав аппаратов, количество линий, алгоритм и исполнение корпуса.`],
    ['Как узнать точную цену?', 'Пришлите схему или исходные данные. Стоимость зависит от номиналов, производителя компонентов, габаритов и дополнительных функций.'],
    ['Какая аппаратура используется?', 'По согласованию применяем компоненты премиального, стандартного или бюджетного сегмента. Все замены фиксируются до начала производства.'],
    ['Как заказать изделие?', 'Оставьте запрос на сайте, по телефону или электронной почте. Инженер уточнит данные, после чего вы получите коммерческое предложение.']
  ];
  return `<main id="main">${pageHero(m.title, m.intro, '08', cat?.title || 'Каталог')}
    <section class="section"><div class="shell product-layout"><div class="product-gallery reveal"><img src="${m.image}" alt="${m.title}"></div><aside class="buy-panel"><span class="buy-panel__code">Модель · ${m.code}</span><h2>Изготовим под параметры объекта</h2><p>${m.purpose}</p><ul class="feature-list">${m.features.map(x=>`<li><span>${x}</span></li>`).join('')}</ul><div class="product-price"><strong>Цена по расчёту</strong><span>после согласования<br>комплектации</span></div><a class="btn btn--light" href="/kontakty/#request">Запросить предложение →</a></aside></div></section>
    ${contentBand([['Гарантия до 5 лет','Срок зависит от состава и условий договора.'],['Производство в Минске','Сборка, маркировка и контроль на одном предприятии.'],['Комплектация на выбор','Согласуем производителя и ценовой сегмент.']])}
    <section class="section"><div class="shell article-grid"><div class="article-grid__aside"><p class="eyebrow">Назначение</p><h2>Где применяется ${m.code}</h2><p class="lead">Решение адаптируется под электрические параметры и условия конкретного объекта.</p></div><div><div class="topic-grid">${m.uses.map((x,i)=>`<article class="topic-card"><span class="topic-card__icon">0${i+1}</span><h3>${x}</h3><p>Состав цепей, номиналы защиты и исполнение корпуса определяются рабочей документацией.</p></article>`).join('')}</div></div></div></section>
    <section class="section section--dark"><div class="shell split"><div><p class="eyebrow">Варианты исполнения</p><h2>Конфигурация не ограничена одной типовой схемой</h2><p class="lead">Заказчик может задать требуемые аппараты, способ монтажа, ввод кабелей, степень защиты и дополнительные функции.</p></div><div class="option-list">${m.options.map((x,i)=>`<div><strong>0${i+1}</strong><span>${x}</span></div>`).join('')}</div></div></section>
    <section class="section"><div class="shell"><div class="section-head"><div><p class="eyebrow">Как заказать</p><h2>От исходных данных до готового изделия</h2></div><p>До запуска в производство фиксируем электрическую схему, компоненты, цену и срок.</p></div><div class="process-grid"><article class="process-card" style="color:var(--ink);border-color:var(--line)"><h3>Заявка</h3><p style="color:var(--muted)">Получаем схему, опросный лист или описание задачи.</p></article><article class="process-card" style="color:var(--ink);border-color:var(--line)"><h3>Расчёт</h3><p style="color:var(--muted)">Подбираем аппаратуру и формируем предложение.</p></article><article class="process-card" style="color:var(--ink);border-color:var(--line)"><h3>Производство</h3><p style="color:var(--muted)">Собираем, маркируем и проверяем изделие.</p></article><article class="process-card" style="color:var(--ink);border-color:var(--line)"><h3>Получение</h3><p style="color:var(--muted)">Самовывоз или согласованная доставка на объект.</p></article></div></div></section>
    ${related.length ? `<section class="section"><div class="shell"><div class="section-head"><div><p class="eyebrow">Смотрите также</p><h2>Другие модели категории</h2></div><p>Связанные решения можно объединить в комплект поставки.</p></div><div class="related-grid">${related.map(p=>catalogCard(p[0],p[1],cat?.tag||'Оборудование','Изготовление под заказ по вашей схеме.',p[2],cat?.type||'')).join('')}</div></div></section>`:''}
    ${faqSection(productFaq, `Вопросы про ${m.code}`)}${cta(`Заказать ${m.code} по вашей схеме`)}</main>`;
}

function render() {
  const explicit = document.body.dataset.page;
  const path = location.pathname.endsWith('/') ? location.pathname : `${location.pathname}/`;
  const category = categories.find(c => path === `/${c.slug}/`);
  const modelKey = document.body.dataset.model;
  const page = explicit || pathToPage[path] || (category ? 'category' : modelKey ? 'model' : 'home');
  document.title = modelKey && modelCatalog[modelKey] ? `${modelCatalog[modelKey].title} — купить в Минске | ЭлектроСлужба` : pageTitles[page] || (category ? `${category.title} — ЭлектроСлужба` : pageTitles.home);
  let content = '';
  if (page === 'home') content = homePage();
  else if (page === 'catalog') content = catalogPage();
  else if (page === 'about') content = aboutPage();
  else if (page === 'contacts') content = contactsPage();
  else if (page === 'careers') content = careersPage();
  else if (page === 'delivery') content = deliveryPage();
  else if (page === 'ya5000') content = productPage('ya5000');
  else if (page === 'shasu') content = productPage('shasu');
  else if (page === 'model') content = productPage(modelKey);
  else if (page === 'category') content = categoryPage(document.body.dataset.slug || category?.slug);
  const active = page === 'category' || page === 'catalog' || page === 'model' || page === 'ya5000' || page === 'shasu' ? 'catalog' : page;
  document.body.innerHTML = header(active) + content + footer();
  initInteractions();
}

function initInteractions() {
  const toggle = document.querySelector('.menu-toggle');
  const nav = document.querySelector('.nav-links');
  toggle?.addEventListener('click', () => {
    const open = nav.classList.toggle('open');
    document.body.classList.toggle('menu-open', open);
    toggle.setAttribute('aria-expanded', String(open));
    toggle.setAttribute('aria-label', open ? 'Закрыть меню' : 'Открыть меню');
  });
  nav?.querySelectorAll('a').forEach(a => a.addEventListener('click', () => { nav.classList.remove('open'); document.body.classList.remove('menu-open'); }));

  document.querySelectorAll('.filter-btn').forEach(btn => btn.addEventListener('click', () => {
    document.querySelectorAll('.filter-btn').forEach(b => b.classList.toggle('active', b === btn));
    document.querySelectorAll('.catalog-card').forEach(card => { card.hidden = btn.dataset.filter !== 'all' && card.dataset.type !== btn.dataset.filter; });
  }));

  const form = document.querySelector('#request');
  form?.addEventListener('submit', event => {
    event.preventDefault();
    const status = form.querySelector('.form-status');
    if (!form.checkValidity()) { form.reportValidity(); status.textContent = 'Заполните имя и телефон.'; return; }
    const data = new FormData(form);
    const subject = `Запрос расчёта: ${data.get('product')}`;
    const body = `Имя: ${data.get('name')}\nТелефон: ${data.get('phone')}\nНаправление: ${data.get('product')}\n\nОписание:\n${data.get('message') || 'Не указано'}`;
    status.textContent = 'Письмо подготовлено. Открываем почтовую программу…';
    window.location.href = `mailto:info@esle.by?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
  });

  const back = document.querySelector('.back-top');
  const updateBack = () => back?.classList.toggle('visible', scrollY > 600);
  addEventListener('scroll', updateBack, { passive: true }); updateBack();
  back?.addEventListener('click', () => scrollTo({ top: 0, behavior: 'smooth' }));

  if ('IntersectionObserver' in window) {
    const observer = new IntersectionObserver(entries => entries.forEach(e => { if (e.isIntersecting) { e.target.classList.add('is-visible'); observer.unobserve(e.target); } }), { threshold: .08 });
    document.querySelectorAll('.reveal').forEach(el => observer.observe(el));
  } else document.querySelectorAll('.reveal').forEach(el => el.classList.add('is-visible'));
}

render();
